// 1. 取得 HTTP Request 的輸出
const items = $input.all();
if (items.length === 0) return [];

const response = items[0].json;
let raw = response.candidates[0].content.parts[0].text;

// 2. 移除 ```json ``` 標記
raw = raw.replace(/^```json\s*|\s*```$/g, "").trim();

// 3. 找到最外層中括號範圍
const start = raw.indexOf('[');
const end = raw.lastIndexOf(']');
if (start === -1 || end === -1 || end <= start) {
  throw new Error('無法在回傳中找到完整的 JSON 陣列');
}

// 4. 擷取陣列字串並解析
const jsonText = raw.slice(start, end + 1);
let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (e) {
  throw new Error(`截取後 JSON 解析錯誤：${e.message}`);
}

// 5. 回傳每段新聞為一筆 item
return parsed.map(p => ({ json: p }));

// 1. 取出 OpenAI 回傳的原始 content 字串
const raw = $input.all()[0].json.choices[0].message.content;

// 2. 去除 ```json 和 ``` fence
const cleaned = raw
  .replace(/```json\s*/, '')   // 去掉開頭 ```json
  .replace(/```$/, '')         // 去掉尾端 ```
  .trim();

// 3. 解析成物件
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`無法解析回傳內容: ${e.message}\n解析前字串：\n${cleaned}`);
}

// 4. 解構需要的欄位
const { correct, rationale, causal } = parsed;

// 5. 回傳成新的 item
return [
  {
    json: {
      correct,
      rationale,
      causal
    }
  }
];

